@dc.dataclass
class SystevisorHealthRuntimeCheck:
    effect: SystevisorRunHealthProbeEffect
    callback: ta.Callable[[SystevisorHealthProbeResultFact], None]
    deadline_at: float
    handler: ta.Optional[FdioHandler] = None
    command_run_id: ta.Optional[SystevisorRunId] = None
    finished: bool = False


class SystevisorHealthConnectFdioHandler(FdioHandler):
    def __init__(
            self,
            sock: socket.socket,
            callback: ta.Callable[[ta.Optional[socket.socket], ta.Optional[str]], None],
    ) -> None:
        self._sock: ta.Optional[socket.socket] = sock
        self._callback = callback

    def fd(self) -> int:
        if self._sock is None:
            return -1
        return self._sock.fileno()

    @property
    def closed(self) -> bool:
        return self._sock is None

    def close(self) -> None:
        if self._sock is not None:
            self._sock.close()
            self._sock = None

    def writable(self) -> bool:
        return self._sock is not None

    def on_writable(self) -> None:
        sock = self._sock
        if sock is None:
            return
        error_number = sock.getsockopt(socket.SOL_SOCKET, socket.SO_ERROR)
        if error_number:
            self.close()
            self._callback(None, _systevisor_health_os_error_message(error_number))
            return
        self._sock = None
        self._callback(sock, None)

    def on_error(self, exc: ta.Optional[BaseException] = None) -> None:
        self.close()
        self._callback(None, str(exc) if exc is not None else 'socket connection failed')


def _systevisor_health_os_error_message(error_number: int) -> str:
    return f'[Errno {error_number}] {errno.errorcode.get(error_number, "socket error")}'


@dc.dataclass(frozen=True)
class SystevisorHttpHealthResult:
    success: bool
    message: str
    status: ta.Optional[int] = None


class SystevisorHttpHealthIoPipelineHandler(IoPipelineHandler):
    def __init__(
            self,
            request: FullIoPipelineHttpRequest,
            expected_statuses: ta.Container[int],
    ) -> None:
        super().__init__()
        self._request = request
        self._expected_statuses = expected_statuses
        self._status: ta.Optional[int] = None
        self.result: ta.Optional[SystevisorHttpHealthResult] = None

    def inbound(self, ctx: IoPipelineHandlerContext, msg: ta.Any) -> None:
        if isinstance(msg, IoPipelineMessages.InitialInput):
            ctx.feed_in(msg)
            ctx.feed_out(self._request)
            return
        if isinstance(msg, IoPipelineHttpResponseHead):
            self._status = msg.status
            return
        if isinstance(msg, IoPipelineHttpResponseEnd):
            if self._status is None:
                self.result = SystevisorHttpHealthResult(False, 'response ended without a status')
            else:
                self.result = SystevisorHttpHealthResult(
                    self._status in self._expected_statuses,
                    f'HTTP status {self._status}',
                    self._status,
                )
            ctx.feed_final_output()
            return
        if isinstance(msg, IoPipelineHttpResponseAborted):
            self.result = SystevisorHttpHealthResult(False, 'HTTP response aborted')
            ctx.feed_final_output()
            return
        if isinstance(msg, IoPipelineMessages.FinalInput):
            self.result = SystevisorHttpHealthResult(False, 'connection closed before HTTP response completed')
            ctx.feed_in(msg)
            ctx.feed_final_output()
            return
        if isinstance(msg, IoPipelineMessages.Error):
            self.result = SystevisorHttpHealthResult(False, str(msg.exc))
            ctx.feed_final_output()
            return
        ctx.feed_in(msg)


class SystevisorHttpHealthFdioHandler(IoPipelineDriverSocketFdioHandler):
    def __init__(
            self,
            sock: socket.socket,
            addr: ta.Any,
            response_handler: SystevisorHttpHealthIoPipelineHandler,
            callback: ta.Callable[[SystevisorHttpHealthResult], None],
    ) -> None:
        self._systevisor_response_handler = response_handler
        self._systevisor_callback = callback
        self._systevisor_reported = False
        super().__init__(sock, addr, IoPipeline.Spec([
            IoPipelineHttpRequestEncoder(),
            IoPipelineHttpClientResponseDecoder(),
            response_handler,
        ]))

    def _systevisor_after_io(self) -> None:
        result = self._systevisor_response_handler.result
        if result is not None and not self._systevisor_reported:
            self._systevisor_reported = True
            self._systevisor_callback(result)

    def _systevisor_io(self, method: ta.Callable[[], None]) -> None:
        try:
            method()
        except BaseException as exc:  # noqa: BLE001
            if not self._systevisor_reported:
                self._systevisor_reported = True
                self._systevisor_callback(SystevisorHttpHealthResult(False, str(exc)))
        finally:
            self._systevisor_after_io()

    def on_readable(self) -> None:
        self._systevisor_io(super().on_readable)

    def on_writable(self) -> None:
        self._systevisor_io(super().on_writable)

    def on_timeout(self) -> None:
        self._systevisor_io(super().on_timeout)


class SystevisorFdioHealthProbeRunner(SystevisorHealthProbeRunner, FdioHandler):
    def __init__(
            self,
            process_manager: SystevisorProcessManager,
            fdio_manager: FdioManager,
            clock: SystevisorClock,
            log_manager: SystevisorLogManager,
    ) -> None:
        self._process_manager = process_manager
        self._fdio_manager = fdio_manager
        self._clock = clock
        self._log_manager = log_manager
        self._checks: ta.Dict[SystevisorHealthCheckId, SystevisorHealthRuntimeCheck] = {}
        self._command_checks: ta.Dict[SystevisorRunId, SystevisorHealthRuntimeCheck] = {}
        self._closed = False
        fdio_manager.register(self)

    def fd(self) -> int:
        return -1

    @property
    def closed(self) -> bool:
        return self._closed

    def close(self) -> None:
        if self._closed:
            return
        for check in tuple(self._checks.values()):
            if check.handler is not None:
                check.handler.close()
            if check.command_run_id is not None:
                try:
                    self._signal_command(check.command_run_id)
                except SystevisorProcessOwnershipError:
                    pass
        self._checks.clear()
        self._closed = True

    def next_deadline(self) -> ta.Optional[float]:
        if not self._checks:
            return None
        return min(check.deadline_at for check in self._checks.values())

    def on_timeout(self) -> None:
        now = self._clock.monotonic()
        for check in tuple(self._checks.values()):
            if check.deadline_at > now:
                continue
            if check.command_run_id is not None:
                try:
                    self._signal_command(check.command_run_id)
                except SystevisorProcessOwnershipError:
                    pass
            self._finish(check, False, f'probe timed out after {check.effect.probe.timeout_secs:g}s')

    def start(
            self,
            effect: SystevisorRunHealthProbeEffect,
            callback: ta.Callable[[SystevisorHealthProbeResultFact], None],
    ) -> SystevisorHealthProbeRuntimeStart:
        if self._closed:
            raise RuntimeError('health probe runner is closed')
        if effect.check_id in self._checks:
            raise RuntimeError(f'health check is already active: {effect.check_id}')
        check = SystevisorHealthRuntimeCheck(
            effect=effect,
            callback=callback,
            deadline_at=self._clock.monotonic() + effect.probe.timeout_secs,
        )
        self._checks[effect.check_id] = check

        kind = effect.probe.kind
        if kind is SystevisorHealthProbeKind.PROCESS:
            state = self._process_manager.get_state(effect.run_id)
            success = state is not None and state.status is SystevisorOwnedProcessStatus.RUNNING
            self._finish(check, success, 'owned process is running' if success else 'owned process is not running')
        elif kind is SystevisorHealthProbeKind.LOG_ACTIVITY:
            self._start_log_activity(check)
        elif kind is SystevisorHealthProbeKind.TCP:
            self._start_connect(check, http=False)
        elif kind is SystevisorHealthProbeKind.HTTP:
            self._start_connect(check, http=True)
        elif kind is SystevisorHealthProbeKind.COMMAND:
            self._start_command(check)
        else:
            raise TypeError(kind)
        return SystevisorHealthProbeRuntimeStart(command_run_id=check.command_run_id)

    def owns_command_run(self, run_id: SystevisorRunId) -> bool:
        return run_id in self._command_checks

    def command_exec_result(self, result: SystevisorProcessExecResult) -> None:
        check = self._command_checks[result.run_id]
        if not result.succeeded:
            self._finish(check, False, result.message or 'health command exec failed')

    def command_exit(self, observed: SystevisorObservedProcessExit) -> None:
        check = self._command_checks.pop(observed.run_id)
        if not check.finished:
            self._finish(
                check,
                observed.return_code == 0,
                f'health command exited with status {observed.return_code}',
                {'return_code': observed.return_code},
            )

    def _start_log_activity(self, check: SystevisorHealthRuntimeCheck) -> None:
        probe = check.effect.probe
        if probe.channel is None or probe.max_quiet_secs is None:
            self._finish(check, False, 'log activity probe is missing its channel policy')
            return
        stream = SystevisorLogStream(probe.channel)
        last_activity_at = self._log_manager.last_activity_at(check.effect.run_id, stream)
        if last_activity_at is None:
            self._finish(check, False, f'{stream.value} is not captured')
            return
        quiet_secs = max(0., self._clock.monotonic() - last_activity_at)
        self._finish(
            check,
            quiet_secs <= probe.max_quiet_secs,
            f'{stream.value} quiet for {quiet_secs:g}s',
            {'quiet_secs': quiet_secs, 'last_activity_at': last_activity_at},
        )

    def _start_connect(self, check: SystevisorHealthRuntimeCheck, *, http: bool) -> None:
        probe = check.effect.probe
        host: ta.Optional[str]
        port: ta.Optional[int]
        if http:
            parsed = urllib.parse.urlsplit(probe.url or '')
            host = parsed.hostname
            port = parsed.port or 80
        else:
            parsed = None
            host = probe.host
            port = probe.port
        if host is None or port is None:
            self._finish(check, False, 'probe address is incomplete')
            return
        try:
            family, socket_type, protocol, _, address = socket.getaddrinfo(
                host,
                port,
                type=socket.SOCK_STREAM,
            )[0]
            sock = socket.socket(family, socket_type, protocol)
            sock.setblocking(False)
            result = sock.connect_ex(address)
        except OSError as exc:
            self._finish(check, False, str(exc))
            return

        def connected(
                connected_socket: ta.Optional[socket.socket],
                message: ta.Optional[str],
        ) -> None:
            if connected_socket is None:
                self._finish(check, False, message or 'connection failed')
            elif http:
                self._start_http(check, connected_socket, address, parsed)
            else:
                connected_socket.close()
                self._finish(check, True, f'connected to {host}:{port}')

        if result == 0:
            connected(sock, None)
        elif result in {errno.EINPROGRESS, errno.EWOULDBLOCK, errno.EALREADY, errno.EINTR}:
            handler = SystevisorHealthConnectFdioHandler(sock, connected)
            check.handler = handler
            self._fdio_manager.register(handler)
        else:
            sock.close()
            self._finish(check, False, _systevisor_health_os_error_message(result))

    def _start_http(
            self,
            check: SystevisorHealthRuntimeCheck,
            sock: socket.socket,
            address: ta.Any,
            parsed: ta.Any,
    ) -> None:
        probe = check.effect.probe
        target = urllib.parse.urlunsplit(('', '', parsed.path or '/', parsed.query, ''))
        host_header = parsed.hostname or ''
        if parsed.port is not None:
            host_header = f'{host_header}:{parsed.port}'
        request = FullIoPipelineHttpRequest.simple(
            host_header,
            target,
            method=probe.method,
            connection='close',
        )
        response_handler = SystevisorHttpHealthIoPipelineHandler(request, frozenset(probe.expected_statuses))

        def completed(result: SystevisorHttpHealthResult) -> None:
            self._finish(
                check,
                result.success,
                result.message,
                {'status': result.status} if result.status is not None else {},
            )

        handler = SystevisorHttpHealthFdioHandler(sock, address, response_handler, completed)
        check.handler = handler
        try:
            if handler.next(read=False) is not None:
                raise RuntimeError('unexpected HTTP health pipeline output')
        except BaseException as exc:  # noqa: BLE001
            handler.close()
            self._finish(check, False, str(exc))
            return
        if not handler.closed:
            self._fdio_manager.register(handler)

    def _start_command(self, check: SystevisorHealthRuntimeCheck) -> None:
        try:
            run_id, _ = self._process_manager.spawn_health_command(check.effect)
        except (SystevisorProcessSpawnError, OSError) as exc:
            self._finish(check, False, str(exc))
            return
        check.command_run_id = run_id
        self._command_checks[run_id] = check

    def _signal_command(self, run_id: SystevisorRunId) -> None:
        state = self._process_manager.get_state(run_id)
        if state is None:
            raise SystevisorProcessOwnershipError(f'health command is not owned: {run_id}')
        scope = (
            SystevisorSignalScope.SESSION
            if state.session_id == state.pid else
            SystevisorSignalScope.PROCESS
        )
        self._process_manager.signal(run_id, 'KILL', scope)

    def _finish(
            self,
            check: SystevisorHealthRuntimeCheck,
            success: bool,
            message: str,
            data: ta.Optional[ta.Mapping[str, ta.Any]] = None,
    ) -> None:
        if check.finished:
            return
        check.finished = True
        self._checks.pop(check.effect.check_id, None)
        if check.handler is not None:
            check.handler.close()
            check.handler = None
        check.callback(SystevisorHealthProbeResultFact(
            check_id=check.effect.check_id,
            run_id=check.effect.run_id,
            success=success,
            message=message,
            data=dict(data or {}),
        ))


########################################
# ../runtime/coordinator.py


_SYSTEVISOR_COORDINATOR_LOG = get_module_logger(globals())


class SystevisorRuntimeCoordinator:
    def __init__(
            self,
            engine: SystevisorEngine,
            process_manager: SystevisorProcessManager,
            fdio_manager: FdioManager,
            clock: SystevisorClock,
            event_bus: SystevisorEventBus,
            log_manager: SystevisorLogManager,
            health_probe_runner: SystevisorHealthProbeRunner,
    ) -> None:
        self._engine = engine
        self._process_manager = process_manager
        self._fdio_manager = fdio_manager
        self._clock = clock
        self._event_bus = event_bus
        self._log_manager = log_manager
        self._health_probe_runner = health_probe_runner

        self._input_queue: ta.Deque[SystevisorEngineInput] = collections.deque()
        self._processing = False
        self._closed = False
        self._exec_handlers: ta.Dict[SystevisorRunId, SystevisorProcessExecFdioHandler] = {}
        self._pidfd_handlers: ta.Dict[SystevisorRunId, SystevisorProcessPidfdFdioHandler] = {}
        self._output_handlers: ta.Dict[SystevisorRunId, ta.List[FdioHandler]] = {}
        self._delivered_exec_results: ta.Set[SystevisorRunId] = set()
        self._failed_exec_runs: ta.Set[SystevisorRunId] = set()
        self._pending_exits: ta.Dict[SystevisorRunId, SystevisorObservedProcessExit] = {}
        self._signal_handler: ta.Optional[SystevisorSignalFdioHandler] = None

        self._deadline_handler = SystevisorDeadlineFdioHandler(clock, self._on_deadline)
        self._wait_handler = SystevisorProcessWaitFdioHandler(
            clock,
            self._observe_process_exits,
            process_manager.needs_wait_polling,
        )
        self._fdio_manager.register(self._deadline_handler)
        self._fdio_manager.register(self._wait_handler)

    @property
    def engine(self) -> SystevisorEngine:
        return self._engine

    @property
    def event_bus(self) -> SystevisorEventBus:
        return self._event_bus

    @property
    def log_manager(self) -> SystevisorLogManager:
        return self._log_manager

    def install_signal_handler(self, signal_numbers: ta.Iterable[int] = ()) -> None:
        if self._signal_handler is not None:
            raise RuntimeError('signal handler is already installed')
        handler = (
            SystevisorSignalFdioHandler(self._on_signal, signal_numbers)
            if signal_numbers else
            SystevisorSignalFdioHandler(self._on_signal)
        )
        handler.install()
        self._signal_handler = handler
        self._fdio_manager.register(handler)

    def submit(self, engine_input: SystevisorEngineInput) -> ta.Sequence[SystevisorEngineOutput]:
        if self._closed:
            raise RuntimeError('runtime coordinator is closed')
        self._input_queue.append(engine_input)
        if self._processing:
            return ()

        outputs: ta.List[SystevisorEngineOutput] = []
        self._processing = True
        try:
            while self._input_queue:
                current_input = self._input_queue.popleft()
                if isinstance(current_input, SystevisorApplySnapshotCommand):
                    self._process_manager.set_reap_unknown_children(
                        current_input.snapshot.config.manager.reap_unknown_children,
                    )
                    self._wait_handler.poke()
                output = self._engine.step(current_input, self._clock.monotonic())
                if isinstance(current_input, SystevisorApplySnapshotCommand):
                    self._log_manager.set_default_strip_ansi(current_input.snapshot.config.manager.strip_ansi)
                    self._event_bus.set_journal_capacity(current_input.snapshot.config.api.event_backlog)
                outputs.append(output)
                for event in output.events:
                    _, failures = self._event_bus.publish('engine', event, self._clock.monotonic())
                    for failure in failures:
                        _SYSTEVISOR_COORDINATOR_LOG.error(
                            'Systevisor event subscriber %s failed',
                            failure.subscription_id,
                            exc_info=(
                                type(failure.exception),
                                failure.exception,
                                failure.exception.__traceback__,
                            ),
                        )
                for effect in output.effects:
                    self._execute_effect(effect)
        finally:
            self._processing = False
        return tuple(outputs)

    def _execute_effect(self, effect: SystevisorEngineEffect) -> None:
        if isinstance(effect, SystevisorSpawnProcessEffect):
            self._spawn(effect)
        elif isinstance(effect, SystevisorSignalProcessEffect):
            self._process_manager.signal_effect(effect)
        elif isinstance(effect, SystevisorScheduleDeadlineEffect):
            self._deadline_handler.schedule(effect)
        elif isinstance(effect, SystevisorApplyLiveConfigEffect):
            self._log_manager.update_process(effect)
        elif isinstance(effect, SystevisorRunHealthProbeEffect):
            self._run_health_probe(effect)
        else:
            raise TypeError(effect)

    def _on_deadline(self, fact: SystevisorEngineInput) -> None:
        self.submit(fact)

    def _spawn(self, effect: SystevisorSpawnProcessEffect) -> None:
        try:
            spawned = self._process_manager.spawn(effect)
        except (SystevisorProcessSpawnError, OSError) as exc:
            self._input_queue.append(SystevisorSpawnFailedFact(effect.run_id, str(exc)))
            return

        stdout_fd = self._process_manager.take_output_fd(
            effect.run_id,
            SystevisorProcessOutputChannel.STDOUT,
        )
        stderr_fd = self._process_manager.take_output_fd(
            effect.run_id,
            SystevisorProcessOutputChannel.STDERR,
        )
        output_handlers: ta.List[FdioHandler] = list(
            self._log_manager.register_process(effect, stdout_fd, stderr_fd),
        )
        self._output_handlers[effect.run_id] = output_handlers
        for handler in output_handlers:
            self._fdio_manager.register(handler)

        exec_error_fd = spawned.state.exec_error_fd
        if exec_error_fd is None:
            raise RuntimeError('spawned process has no exec handshake fd')
        def exec_ready(run_id: SystevisorRunId = effect.run_id) -> bool:
            return self._on_exec_ready(run_id)

        exec_handler = SystevisorProcessExecFdioHandler(exec_error_fd, exec_ready)
        self._exec_handlers[effect.run_id] = exec_handler
        self._fdio_manager.register(exec_handler)

        if spawned.state.pidfd is not None:
            pidfd_handler = SystevisorProcessPidfdFdioHandler(
                spawned.state.pidfd,
                self._observe_process_exits,
            )
            self._pidfd_handlers[effect.run_id] = pidfd_handler
            self._fdio_manager.register(pidfd_handler)
        self._wait_handler.poke()

    def _run_health_probe(self, effect: SystevisorRunHealthProbeEffect) -> None:
        started = self._health_probe_runner.start(effect, self._on_health_probe_result)
        run_id = started.command_run_id
        if run_id is None:
            return
        state = self._process_manager.get_state(run_id)
        if state is None or state.exec_error_fd is None:
            raise RuntimeError('spawned health command has no exec handshake fd')

        def exec_ready(command_run_id: SystevisorRunId = run_id) -> bool:
            return self._on_exec_ready(command_run_id)

        exec_handler = SystevisorProcessExecFdioHandler(state.exec_error_fd, exec_ready)
        self._exec_handlers[run_id] = exec_handler
        self._fdio_manager.register(exec_handler)
        if state.pidfd is not None:
            pidfd_handler = SystevisorProcessPidfdFdioHandler(
                state.pidfd,
                self._observe_process_exits,
            )
            self._pidfd_handlers[run_id] = pidfd_handler
            self._fdio_manager.register(pidfd_handler)
        self._wait_handler.poke()

    def _on_health_probe_result(self, fact: SystevisorHealthProbeResultFact) -> None:
        self.submit(fact)

    def _on_exec_ready(self, run_id: SystevisorRunId) -> bool:
        result = self._process_manager.poll_exec_result(run_id)
        if result is None:
            return False
        self._handle_exec_result(result)
        pending_exit = self._pending_exits.pop(run_id, None)
        if pending_exit is not None:
            self._complete_process_exit(pending_exit)
        return True

    def _handle_exec_result(self, result: SystevisorProcessExecResult) -> None:
        if result.run_id in self._delivered_exec_results:
            return
        self._delivered_exec_results.add(result.run_id)
        exec_handler = self._exec_handlers.pop(result.run_id, None)
        if exec_handler is not None:
            exec_handler.close()
        if self._health_probe_runner.owns_command_run(result.run_id):
            self._health_probe_runner.command_exec_result(result)
            return
        if result.succeeded:
            self.submit(SystevisorSpawnSucceededFact(result.run_id))
        else:
            self._failed_exec_runs.add(result.run_id)
            self.submit(SystevisorSpawnFailedFact(result.run_id, result.message or 'child setup failed'))

    def _observe_process_exits(self) -> None:
        for observed in self._process_manager.poll_exits():
            if observed.run_id not in self._delivered_exec_results:
                result = self._process_manager.poll_exec_result(observed.run_id)
                if result is None:
                    self._pending_exits[observed.run_id] = observed
                    continue
                self._handle_exec_result(result)
            self._complete_process_exit(observed)
        for unknown in self._process_manager.poll_unknown_exits():
            self._event_bus.publish('runtime.unknown_child_reaped', unknown, self._clock.monotonic())

    def _complete_process_exit(self, observed: SystevisorObservedProcessExit) -> None:
        pidfd_handler = self._pidfd_handlers.pop(observed.run_id, None)
        if pidfd_handler is not None:
            pidfd_handler.close()
        self._process_manager.acknowledge_exit(observed.run_id)
        if self._health_probe_runner.owns_command_run(observed.run_id):
            self._health_probe_runner.command_exit(observed)
            self._delivered_exec_results.discard(observed.run_id)
            self._pending_exits.pop(observed.run_id, None)
            return
        self._log_manager.retire_process(observed.run_id)
        if observed.run_id in self._failed_exec_runs:
            self._failed_exec_runs.remove(observed.run_id)
        else:
            self.submit(SystevisorProcessExitedFact(observed.run_id, observed.return_code))
        self._delivered_exec_results.discard(observed.run_id)
        self._pending_exits.pop(observed.run_id, None)

    def _on_signal(self, received: SystevisorReceivedSignal) -> None:
        if received.signal_number == signal.SIGCHLD:
            self._observe_process_exits()
        elif received.signal_number in {signal.SIGTERM, signal.SIGINT, signal.SIGQUIT}:
            self.submit(SystevisorShutdownCommand())
        elif received.signal_number == signal.SIGHUP:
            self._event_bus.publish('runtime.reload_requested', received, self._clock.monotonic())
        else:
            self._event_bus.publish('runtime.signal', received, self._clock.monotonic())

    def poll(self, timeout: ta.Optional[float] = None) -> None:
        self._fdio_manager.poll(timeout=timeout)
        for run_id in tuple(self._output_handlers):
            if all(handler.closed for handler in self._output_handlers[run_id]):
                del self._output_handlers[run_id]

    def close(self) -> None:
        if self._closed:
            return
        if self._signal_handler is not None:
            self._signal_handler.close()
            self._signal_handler = None
        for exec_handler in self._exec_handlers.values():
            exec_handler.close()
        for pidfd_handler in self._pidfd_handlers.values():
            pidfd_handler.close()
        for handlers in self._output_handlers.values():
            for output_handler in handlers:
                output_handler.close()
        self._deadline_handler.close()
        self._wait_handler.close()
        self._health_probe_runner.close()
        self._log_manager.close()
        self._closed = True


